import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Drawer } from '@/components/ui/drawer';
import { IconButton } from '@/components/ui/icon-button';
import { MenuIcon, CloseIcon, HomeIcon, PlusIcon, RssIcon } from '@/components/ui/icons';

export const Navigation = () => {
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const pathname = usePathname();

  const toggleDrawer = () => {
    setIsDrawerOpen(!isDrawerOpen);
  };

  const closeDrawer = () => {
    setIsDrawerOpen(false);
  };

  return (
    <>
      {/* Hamburger Menu Button */}
      <div className="fixed top-4 left-4 z-30">
        <IconButton
          icon={<MenuIcon />}
          label="Menu"
          variant="ghost"
          onClick={toggleDrawer}
        />
      </div>

      {/* Navigation Drawer */}
      <Drawer isOpen={isDrawerOpen} onClose={closeDrawer}>
        <div className="flex flex-col h-full">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)]">Menu</h2>
            <IconButton
              icon={<CloseIcon />}
              label="Close"
              variant="ghost"
              onClick={closeDrawer}
            />
          </div>

          <nav className="flex-1">
            <ul className="space-y-2">
              <li>
                <Link 
                  href="/" 
                  className={`flex items-center gap-3 p-2 rounded-lg transition-colors ${
                    pathname === '/' 
                      ? 'bg-[var(--background-hover)] text-[var(--primary)]' 
                      : 'text-[var(--text-primary)] hover:bg-[var(--background-hover)]'
                  }`}
                  onClick={closeDrawer}
                >
                  <HomeIcon />
                  <span>Home</span>
                </Link>
              </li>
              <li>
                <Link 
                  href="/manage" 
                  className={`flex items-center gap-3 p-2 rounded-lg transition-colors ${
                    pathname === '/manage' 
                      ? 'bg-[var(--background-hover)] text-[var(--primary)]' 
                      : 'text-[var(--text-primary)] hover:bg-[var(--background-hover)]'
                  }`}
                  onClick={closeDrawer}
                >
                  <PlusIcon />
                  <span>Add Feeds</span>
                </Link>
              </li>
            </ul>
          </nav>

          <div className="mt-auto pt-4 border-t border-[var(--border)]">
            <div className="flex items-center gap-2 text-[var(--text-secondary)]">
              <RssIcon />
              <span className="text-sm">Infrss Reader</span>
            </div>
          </div>
        </div>
      </Drawer>
    </>
  );
}; 